def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

start_n = 999981
end_n = start_n + 37

s_values = {}
any_divisible_by_11 = False

for k in range(start_n, end_n + 1):
    s_k = sum_digits(k)
    s_values[k] = s_k
    if s_k % 11 == 0:
        any_divisible_by_11 = True

print("--- S(k) Values ---")
for k in range(start_n, end_n + 1):
    print(f"S({k}) = {s_values[k]}")

print("\n--- Verification Result ---")
print(f"Is any S(k) divisible by 11? {any_divisible_by_11}")

def S(n):
    return sum(int(d) for d in str(n))

start_n = 999981
end_n = 999981 + 37 # 1000018

results = {}
all_good = True
for k in range(start_n, end_n + 1):
    s_k = S(k)
    is_multiple_of_11 = (s_k % 11 == 0)
    results[k] = (s_k, is_multiple_of_11)
    if is_multiple_of_11:
        all_good = False

print(f"Verification for n={start_n}:")
print(f"Product S(n)...S(n+37) is NOT a multiple of 11: {all_good}")

